def check(call, expected):
    try:
        actual = repr(call())
    except Exception as error:
        actual = type(error).__name__ + ': ' + str(error)
    if actual != expected:
        raise AssertionError(actual + ' != ' + expected)

import math
import random

check(lambda: math.gamma(0.5), '1.7724538509055159')
check(lambda: math.lgamma(0.5), '0.5723649429247004')
