draws = []
for seed in range(20):
    random.seed(seed)
    draws.append([random.binomialvariate(n, p) for n, p in [(100, 0.5), (20, 0.5), (1000, 0.3), (50, 0.9), (10**9, 0.25), (21, 0.5)]])
